/** Display name for an ISO2 code from either table, or the code itself. */
export function countryName(iso: string): string {
  return COUNTRY_NAMES[iso] ?? EXTRA_COUNTRY_NAMES[iso] ?? iso;
}

/** True when the code has an outline we can draw and highlight. */
export function hasOutline(iso: string): boolean {
  return iso in COUNTRY_NAMES;
}
